def entries():
    return f'''<div class="entrygrid"><div class="entry"><span class="entryicon">{icon('group')}</span><h3>Bring your people.</h3><p>Host ready-made trivia<br>or create your own quiz.</p>{button('Create a room')}</div><div class="entry"><span class="entryicon">{icon('play')}</span><h3>Got an invite?</h3><p>Enter your six-character<br>room code to join.</p><div class="code">ABC123 {icon('arrow')}</div></div><div class="entry"><span class="entryicon">{icon('spark')}</span><div><h3>Go solo.</h3><p>A little challenge.<br>All for yourself.</p></div>{button('Play solo','secondary')}</div></div>'''
def desktop(kind):
    hero=f'''<div class="hero"><div class="pill"><span class="dot"></span> A LITTLE FRIENDLY COMPETITION</div><h2>Play together.<br><em>Grow curious.</em></h2><p>Good questions. Great company. Turn what you know into your next good time.</p><div class="social"><div class="facepile">{avatar(21)}{avatar(42)}{avatar(58)}</div><div><b>Better with your people.</b><br><span>No sign-up needed to join.</span></div></div></div>'''
    if kind=='arcade':
        hero=hero.replace('Play together.<br><em>Grow curious.</em>','Big brains.<br><em>Bigger energy.</em>')
        visual=f'<div class="orbit"></div><div class="herofaces">{avatar(21)}{avatar(42)}</div>'
    elif kind=='mint':
        hero=hero.replace('Play together.<br><em>Grow curious.</em>','A little curiosity.<br><em>A lot of possibility.</em>')
        visual=avatar(21,'floating')+avatar(42,'floating second')
    else:
        visual=f'<div class="mosaic"><div class="tile blue"><strong>PLAY.<br>LEARN.<br>REPEAT.</strong>{avatar(21)}</div><div class="tile purple"><strong>Better<br>together.</strong>{avatar(42)}</div><div class="tile gold"><strong>Your next<br>big win.</strong>{trophy()}</div></div>'
    rail=f'<aside class="rail"><span class="active">{icon("home")}</span>{icon("group")}{icon("book")}{icon("cup")}</aside>' if kind=='arcade' else ''
    return f'''<div class="screen desktop"><nav><div class="brand"><span class="brandmark">{icon('spark')}</span>quiz<span style="color:var(--primary)">.</span></div><div class="navlinks"><b style="color:var(--ink)">Play</b><span>How it works</span></div><div class="navright">Log in {button('Create account','secondary')}</div></nav><div class="desktop-content">{rail}<main><div class="homehero">{hero}{visual}</div>{entries()}<div class="appfoot"><span>Free to play. No downloads. Just curiosity.</span><span>Made for good company ↗</span></div></main></div></div>'''
def phonehead(title):
    return f'<div class="status"><span>9:41</span><span class="signal">▮▮▮ ▰</span></div><div class="phonehead"><span class="circle">{icon("close")}</span><div><div class="roomtag">ROOM ABC123</div>{title}</div><span class="circle">···</span></div>'
def question():
    answers=''.join(f'<div class="answer {"selected" if i==1 else ""}"><b>{chr(65+i)}</b>{txt}{icon("check") if i==1 else ""}</div>' for i,txt in enumerate(['Venus','Mars','Jupiter','Saturn']))
    return f'''<div class="screen phone question">{phonehead('General knowledge')}<div class="track"><span></span></div><div class="qmeta"><span>QUESTION 07 / 10</span><span class="timer">08</span></div><div class="q-card"><span class="eyebrow">SPACE & SCIENCE</span><h3>Which planet is<br>known as the<br>Red Planet?</h3></div><div class="answers">{answers}</div><div class="submit">{button('Lock in answer')}</div><div class="hint">Choose one answer before the timer ends.</div><div class="phone-footer">{avatar(21)}<b>Alex · You</b><strong>600 pts</strong></div></div>'''
def result():
    people=''
    for cls,num,name,score,rank in [('second',42,'Jamie','700',2),('first',21,'Alex · You','800',1),('third',58,'Sam','600',3)]:
        crown=f'<span class="crown">{icon("cup")}</span>' if rank==1 else ''
        people+=f'<div class="person {cls}">{crown}{avatar(num)}<small>{name}</small><span class="score">{score} pts</span><div class="step">{rank}</div></div>'
    return f'''<div class="screen phone result">{phonehead('The results')}<div class="resulttitle"><span class="pill">QUIZ COMPLETE</span><h3>Look at you go!</h3><p>Great guesses. A well-earned win.<br>Here’s how your room finished.</p></div><div class="podium">{people}</div><div class="resultstats"><div><strong>800</strong><small>YOUR POINTS</small></div><div><strong>8 / 10</strong><small>CORRECT ANSWERS</small></div></div><div class="submit">{button('Ready to play again')}</div>{button('Back to home','secondary')}<div class="hint">The host will set up your next round.</div></div>'''
