for c in configs:
    variables=';'.join(f'--{k}:{c[k]}' for k in ['ink','muted','board','bg','card','primary','on','deep','soft','line'])
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{c['name']} — Quiz design concept</title><style>{fonts}{CSS}:root{{{variables}}}</style></head><body class="{c['kind']}"><div class="board"><header class="boardhead"><div><div class="label">QUIZ / DESIGN EXPLORATION / {c['tag']}</div><h1>{c['id'].upper()} — {c['name']}</h1><p>{c['desc']}</p></div><div class="conceptnum">{c['id'].upper()}</div></header><div class="screens"><section><div class="caption"><span>01 / Home · Desktop</span><span>Host · Join · Solo</span></div>{desktop(c['kind'])}</section><section><div class="caption"><span>02 / Live question</span></div>{question()}</section><section><div class="caption"><span>03 / Room results</span></div>{result()}</section></div><footer class="boardfoot"><div><strong>{c['why']}</strong>{c['detail']}<div class="swatches">{''.join(f'<i style="background:{color}"></i>' for color in c['colors'])}</div></div><div><strong>{c['layout']}</strong>{c['layoutdetail']}</div><div><strong>Concept only · Existing app flows</strong>Uses the current avatar collection and points system. Sample names and scores. No application UI changed.</div></footer></div></body></html>'''
    (OUT/f'{c["id"]}-{c["kind"]}.html').write_text(html)
print('Created 3 self-contained HTML concept boards.')
# Keep the question controls clear of the persistent player footer.
polish='''.question .phonehead{margin-bottom:18px}.question .track{margin-bottom:16px}.question .q-card{min-height:145px;padding:16px}.question .q-card h3{font-size:22px;margin-top:13px}.question .answers{gap:8px;margin-top:14px}.question .answer{padding:8px}.question .answer.selected{padding:7px}.question .submit{margin-top:15px}.question .hint{margin-top:9px}.result .podium{margin-top:32px}'''
for c in configs:
    f=OUT/f'{c["id"]}-{c["kind"]}.html'
    f.write_text(f.read_text().replace('</style>',polish+'</style>'))
